Translate("frFR", "alterac-mountains", {
	title = "Montagnes d'Alterac",
	aliases = { "Alterac", "royaume d'Alterac" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les montagnes d'Alterac s'élèvent au nord des {link:hillsbrad-foothills}Contreforts d'Hillsbrad{/link}, un mur de neige et de pierre grise entre les rives du {red:lordamere-lake}Lac Lordamere{/red} et les terres mortes des {link:eastern-plaguelands}Maleterres{/link}. Elles formaient jadis un royaume à part entière. Sa capitale gît brisée dans les hauts cols, et son nom se prononce encore comme une malédiction dans les cours des hommes, car Alterac trahit l'{link:alliance}Alliance{/link} à l'heure la plus sombre. Aujourd'hui, les montagnes appartiennent à qui peut les tenir : nobles exilés et leurs coupe-jarrets, ogres couronnés de reliques volées, sorciers, assassins, orcs et nains.]=],
		},
		{
			title = "Origines",
			text = [=[Alterac fut l'une des cités-États que les humains d'{link:arathor}Arathor{/link} fondèrent dans les terres sauvages après la mort du roi {link:thoradin}Thoradin{/link}, quand leur empire déborda des murs de {link:stromgarde-keep}Strom{/link}. Elle prospéra grâce aux routes qui traversaient les montagnes, et devint avec le temps l'un des royaumes humains qui se partagèrent l'ancien empire. La famille Perenolde la gouvernait depuis un château de la haute cité. Les fermes des {link:the-uplands}Hauteurs{/link} la nourrissaient, et les magi de {link:dalaran}Dalaran{/link} étaient ses voisins de l'autre côté du lac.]=],
		},
		{
			title = "Le temps présent",
			text = [=[Le {link:syndicate}Syndicat{/link} tient une grande part de l'ancien royaume. Ses seigneurs ont fait de la ville fantôme de {link:strahnbrad}Strahnbrad{/link} leur forteresse et des {link:the-uplands}Hauteurs{/link} leur terrain de chasse, et lord {link:lord-aliden-perenolde}Aliden Perenolde{/link} tient sa cour dans un manoir au bord du lac. Des inconnus en robes noires se tiennent à ses côtés. La capitale en ruine appartient aux ogres {link:crushridge-ogres}Cassecrête{/link} et à leur seigneur de guerre {link:mug-thol}Mug'thol{/link}, qui porte une couronne que {link:sylvanas-windrunner}la Dame noire{/link} veut récupérer. À l'ouest, {link:dalaran}Dalaran{/link} se dresse reconstruite, et sa grande barrière est tombée. À l'est, les assassins de {link:ravenholdt-manor}Ravenholdt{/link} surveillent le Syndicat depuis leur manoir caché. À l'entrée de la vallée d'Alterac, des nains d'{link:kingdom-of-ironforge}Ironforge{/link} et des orcs du {link:frostwolf-clan}clan Frostwolf{/link} rassemblent des soldats pour une guerre qui leur est propre. {link:southshore}Southshore{/link} et {link:tarren-mill}Moulin-de-Tarren{/link} envoient tous deux des chasseurs dans les neiges, chacun pour ses propres raisons.]=],
		},
		{
			title = "Habitants",
			text = [=[• {b}Le {link:syndicate}Syndicat{/link}.{/b} Des nobles déchus d'Alterac, avec les voleurs, les détrousseurs et les mages de l'ombre qui les servent.
• {b}Les ogres {link:crushridge-ogres}Cassecrête{/link}.{/b} Une bande guerrière d'ogres qui a pris la capitale en ruine et creusé un tertre dans les collines au-delà.
• {b}Les magi de {link:dalaran}Dalaran{/link}.{/b} Le {link:kirin-tor}Kirin Tor{/link} et ses gardes, ses ouvriers et ses élémentaires asservis.
• {b}La Ligue des assassins.{/b} Les voleurs de {link:ravenholdt-manor}Ravenholdt{/link}, qui ne répondent à aucun roi.
• {b}La {link:stormpike-guard}Garde Stormpike{/link} et le {link:frostwolf-clan}clan Frostwolf{/link}.{/b} Des nains et des orcs en guerre pour la vallée d'Alterac.
• {b}Les bêtes.{/b} Des yétis dans les grottes, des lions des montagnes sur les pentes et des ours sur les collines basses.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}Le royaume.{/b} Pendant des siècles, Alterac fut un petit mais fier royaume du nord, souvent en querelle avec sa voisine {link:stromgarde-keep}Stromgarde{/link}.
• {b}La {link:second-war}Deuxième Guerre{/link}.{/b} Le roi {link:aiden-perenolde}Aiden Perenolde{/link} douta de l'{link:alliance}Alliance{/link} dès le début. Quand la {link:horde}Horde{/link} atteignit ses montagnes, il conclut un pacte secret avec {link:orgrim-doomhammer}Orgrim Doomhammer{/link} et ouvrit les cols du sud. Les orcs traversèrent en quelques jours au lieu de plusieurs mois et mirent le siège devant la capitale de {link:lordaeron}Lordaeron{/link}.
• {b}La chute.{/b} Quand la trahison fut connue, les armées de l'Alliance marchèrent sur Alterac. Le roi {link:terenas-menethil}Terenas Menethil{/link} déposa Perenolde et le retint prisonnier dans son propre palais. Le royaume ne se releva jamais, et son peuple se dispersa.
• {b}La peste.{/b} Durant la {link:third-war}Troisième Guerre{/link}, le {link:scourge}Fléau{/link} balaya Lordaeron, et {link:archimonde}Archimonde{/link} abattit {link:dalaran}Dalaran{/link} de l'autre côté du lac. Ce qui restait d'ordre dans les montagnes mourut avec eux.]=],
		},
		{
			title = "Légendes des montagnes",
			text = [=[• Le diadème des Perenolde, un bijou de famille de l'ancienne maison royale, fut façonné par les joailliers d'{link:ironforge}Ironforge{/link} et serti d'émeraudes. Il fut perdu à la chute d'Alterac. On dit qu'un {link:ogres}ogre{/link}-mage des {link:crushridge-ogres}Cassecrête{/link} le porte aujourd'hui.
• Le magistrat de {link:southshore}Southshore{/link} fut assassiné par des tueurs que l'on ne retrouva jamais. Son successeur croit que le {link:syndicate}Syndicat{/link} les avait engagés.
• Les chasseurs disent qu'un grand yéti nommé Frostmaw rôde sur les hauteurs au-dessus de la {link:growless-cave}Caverne stérile{/link}.]=],
		},
	},
})

Translate("frFR", "ruins-of-alterac", {
	title = "Ruines d'Alterac",
	aliases = { "Cité d'Alterac" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Ruines d'Alterac furent autrefois la capitale du royaume, une cité fortifiée dans les hauts cols. Ici, le roi {link:aiden-perenolde}Aiden Perenolde{/link} tenait sa cour, et ici il annonça à ses officiers qu'{link:alterac-mountains}Alterac{/link} se rangerait du côté de la {link:horde}Horde{/link}. Quand l'{link:alliance}Alliance{/link} vint le chercher, son peuple s'enfuit, et la cité ne fut jamais reconstruite. Aujourd'hui, les ogres {link:crushridge-ogres}Cassecrête{/link} tiennent les rues brisées. Leur seigneur de guerre {link:mug-thol}Mug'thol{/link} a fait son repaire dans l'ancien palais, le seul édifice encore debout et entier. Les {link:forsaken}Réprouvés{/link} de {link:tarren-mill}Moulin-de-Tarren{/link} ont juré de planter sa tête sur une pique au-dessus de ces murs.]=],
		},
	},
})

Translate("frFR", "strahnbrad", {
	title = "Strahnbrad",
	sections = {
		{
			title = "Résumé",
			text = [=[Strahnbrad était une ville des contreforts de l'est, sur la route entre {link:alterac-mountains}Alterac{/link} et les terres de {link:lordaeron}Lordaeron{/link}. À la veille de la {link:third-war}Troisième Guerre{/link}, des orcs la razzièrent pour y prendre des esclaves, et le prince {link:arthas-menethil}Arthas Menethil{/link} arriva trop tard pour sauver nombre de ses habitants. C'est aujourd'hui une ville fantôme et la principale place forte du {link:syndicate}Syndicat{/link}. Ses seigneurs se réunissent dans ses salles vides, et ses vieilles cellules gardent leurs prisonniers. L'{link:orcs}orc{/link} {link:gol-dir}Gol'dir{/link} y fut retenu comme esclave, forcé de creuser et de porter des charges pour ses geôliers. Le magistrat de {link:southshore}Southshore{/link} veut les chevalières des nobles qui se cachent parmi ses voleurs.]=],
		},
	},
})

Translate("frFR", "crushridge-hold", {
	title = "Bastion Cassecrête",
	aliases = { "Creux du massacre", "Fourche du gibet" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Bastion Cassecrête est le tertre que les ogres {link:crushridge-ogres}Cassecrête{/link} ont creusé dans les collines près de la capitale en ruine. Ses grottes et ses camps grouillent de brutes, de cogneurs et de mages, et plus loin dans les montagnes ils tiennent un second tertre au Creux du massacre. Leurs patrouilles gardent le carrefour de la Fourche du gibet, près d'une vieille tour en ruine. Le maréchal de {link:southshore}Southshore{/link} redoute le jour où les ogres se sentiront assez sûrs d'eux pour descendre dans les contreforts, et il paie bien chaque osselet que ses chasseurs rapportent.]=],
		},
	},
})

Translate("frFR", "the-uplands", {
	title = "Les Hauteurs",
	aliases = { "Hauteurs" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Hauteurs sont les hautes collines du nord d'{link:alterac-mountains}Alterac{/link}, au nord de {link:strahnbrad}Strahnbrad{/link}. C'étaient les terres agricoles de l'ancien royaume. Elles sont aujourd'hui le cœur du {link:syndicate}Syndicat{/link}, qui y est le plus fort. Le baron {link:baron-vardus}Vardus{/link} a ses camps dans ces collines, et ici attendent aussi les mages de l'ombre de {link:argus-wake}l'Argus Wake{/link}, venus à Alterac en alliés du Syndicat. Le magistrat de {link:southshore}Southshore{/link} envoie ses chasseurs au nord, dans les Hauteurs, quand il veut la tête d'un noble.]=],
		},
	},
})

Translate("frFR", "dandred-s-fold", {
	title = "Clos de Dandred",
	aliases = { "Rivage brumeux" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Clos de Dandred est un manoir doté d'un petit port sur le Rivage brumeux, là où l'ouest des {link:the-uplands}Hauteurs{/link} rejoint le {red:lordamere-lake}Lac Lordamere{/red}. C'est la demeure de lord {link:lord-aliden-perenolde}Aliden Perenolde{/link}, qui se dit seigneur de ces terres. Des assassins et des hommes de main du {link:syndicate}Syndicat{/link} gardent ses portes. À l'étage vit sa maîtresse, {link:elysa}Elysa{/link}, et à ses côtés se tient {link:nagaz}Nagaz{/link}, l'{link:orcs}orc{/link} qui parle au nom de {link:argus-wake}l'Argus Wake{/link}. Les guerriers de {link:tarren-mill}Moulin-de-Tarren{/link} connaissent le chemin. Les chasseurs de {link:southshore}Southshore{/link} aussi.]=],
		},
	},
})

Translate("frFR", "sofera-s-naze-and-corrahn-s-dagger", {
	title = "Promontoire de Sofera et Dague de Corrahn",
	aliases = { "Promontoire de Sofera", "Dague de Corrahn" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Promontoire de Sofera et la Dague de Corrahn sont deux collines qui descendent des montagnes vers les contreforts, au nord et à l'ouest de {link:tarren-mill}Moulin-de-Tarren{/link}. Le {link:syndicate}Syndicat{/link} a des camps sur l'une et l'autre. D'ici, ses détrousseurs et ses voleurs descendent piller les routes d'{link:hillsbrad-foothills}Hillsbrad{/link}, et d'ici, croit {link:southshore}Southshore{/link}, vinrent les assassins qui tuèrent son dernier magistrat. Sur une colline près de l'un de ces camps, un homme de main du Syndicat nommé Valik gît blessé, marchandant un dernier verre.]=],
		},
	},
})

Translate("frFR", "growless-cave", {
	title = "Caverne stérile",
	sections = {
		{
			title = "Résumé",
			text = [=[La Caverne stérile s'ouvre dans les froides hauteurs du centre d'{link:alterac-mountains}Alterac{/link}. C'est un repaire de yétis des montagnes, et un yéti blanc nommé Skhowl est parfois aperçu près de son entrée. La caverne a aussi une histoire plus sombre. Le sorcier {link:helcular}Helcular{/link}, qui cherchait à devenir liche, alluma à l'intérieur l'un de ses trois bûchers cérémoniels : la Flamme d'Uzel. Son apprenti de {link:tarren-mill}Moulin-de-Tarren{/link} se souvient encore du chemin. Les chasseurs disent que faire brûler de la viande sur cette flamme fait descendre des sommets le grand yéti Frostmaw.]=],
		},
	},
})

Translate("frFR", "chillwind-point", {
	title = "Pointe du Noroît",
	sections = {
		{
			title = "Résumé",
			text = [=[La Pointe du Noroît est une éminence à l'extrême est d'{link:alterac-mountains}Alterac{/link}, où un vent froid souffle dans un ravin venu des {link:eastern-plaguelands}Maleterres{/link}. Sur elle se dressent les ruines d'un ancien site troll, bien plus vieux que tout royaume humain en ces lieux. Un ermite troll, {link:bath-rah-the-windwatcher}Bath'rah le Guetteur des vents{/link}, a établi son camp au bord de la rivière en contrebas. Il a passé des années à surveiller ces ruines, attendant le jour où un champion viendra affronter le seigneur du vent qui y demeure.]=],
		},
	},
})

Translate("frFR", "ravenholdt-manor", {
	title = "Manoir de Ravenholdt",
	aliases = { "Ravenholdt" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Manoir de Ravenholdt se cache dans les collines de l'est, là où {link:alterac-mountains}Alterac{/link} rejoint {link:hillsbrad-foothills}Hillsbrad{/link}, au-dessus des ruines de {link:durnholde-keep}Durnholde{/link}. Aucune route n'y mène ouvertement. C'est la demeure de lord {link:lord-jorach-ravenholdt}Jorach Ravenholdt{/link} et le siège de la Ligue des assassins. Ici, les meilleurs voleurs et tueurs des terres du nord sont formés, surveillés et mis à l'épreuve. Les étrangers n'y sont pas les bienvenus. Ceux qui arrivent sans y être invités trouvent rarement la porte, et ceux qui sont invités doivent d'abord prouver leur ruse rien que pour l'atteindre. La Ligue est en guerre contre le {link:syndicate}Syndicat{/link} depuis des années.]=],
		},
	},
})

Translate("frFR", "lordamere-internment-camp", {
	title = "Camp d'internement de Lordamere",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Camp d'internement de Lordamere se dresse sur une colline près de {link:dalaran}Dalaran{/link}. Après la {link:second-war}Deuxième Guerre{/link}, ce fut l'un des {link:internment-camps}camps d'internement{/link} de {link:lordaeron}Lordaeron{/link}, où les orcs vaincus étaient retenus derrière des murs. Les orcs sont partis. Aujourd'hui, les {link:the-wizards-of-ambermill}sorciers de Dalaran{/link} se servent du camp comme de leur propre prison. Quatre {link:forsaken}Réprouvés{/link} qui avaient volé des artefacts dans une chambre forte d'{link:undercity}Undercity{/link} s'enfuirent ici, et les magi les capturèrent et les mirent en quarantaine. La gardienne {link:warden-belamoore}Belamoore{/link} tient le camp et étudie ce que portaient les voleurs. La Dame noire veut récupérer ses artefacts.]=],
		},
	},
})

Translate("frFR", "alterac-valley", {
	title = "Vallée d'Alterac",
	sections = {
		{
			title = "Résumé",
			text = [=[Au sud des hauts sommets, un tunnel mène à la vallée d'{link:alterac-mountains}Alterac{/link}, une terre de glace et de pins entre les montagnes. Le clan {link:orcs}orc{/link} {link:frostwolf-clan}Frostwolf{/link} revendique la vallée comme son foyer. Les nains de la {link:stormpike-guard}Garde Stormpike{/link} sont venus y creuser à la recherche de reliques et de minerai, et ils entendent prendre ces terres pour {link:kingdom-of-ironforge}Ironforge{/link}. À l'extérieur du tunnel, les deux armées ont leurs camps. Leurs officiers accueillent les nouvelles recrues, les mettent à l'épreuve et les envoient dans la vallée. Les combats à l'intérieur ne cessent jamais vraiment.]=],
		},
	},
})

Translate("frFR", "old-dalaran-ruins", {
	title = "Old Dalaran Ruins",
	aliases = { "Ruines du vieux Dalaran" },
	sections = {
		{
			title = "Résumé",
			text = [=[{link:dalaran}Dalaran{/link} ne s'est pas relevée tout entière. Quand {link:archimonde}Archimonde{/link} abattit la cité durant la {link:third-war}Troisième Guerre{/link}, ses faubourgs furent brisés en même temps que son cœur. Les magi élevèrent leur nouvelle cité derrière une barrière, mais les ruines de l'ancienne gisent encore sur les rives du {red:lordamere-lake}Lac Lordamere{/red}. Ses sorciers et ses élémentaires asservis les patrouillaient jadis, et des érudits réprouvés croient que des trésors magiques reposent encore parmi les pierres. Maintenant que la barrière est tombée, les ruines sont ouvertes à quiconque est assez hardi pour les fouiller.]=],
		},
	},
})

Translate("frFR", "lord-jorach-ravenholdt", {
	title = "Lord Jorach Ravenholdt",
	subtitle = "Seigneur de la Ligue des assassins",
	found = "À l'intérieur du Manoir de Ravenholdt",
	hint = [=[Trouvez le seigneur du manoir caché des collines de l'est, si ses serviteurs vous laissent entrer.]=],
	allegiance = "Ligue des assassins · Ravenholdt",
	aliases = { "Jorach Ravenholdt", "maître Ravenholdt" },
	sections = {
		{
			title = "Résumé",
			text = [=[Lord Jorach Ravenholdt est le maître du {link:ravenholdt-manor}Manoir de Ravenholdt{/link} et le seigneur de la Ligue des assassins. Ses voleurs sont les plus habiles des terres du nord, et ils ne servent aucun roi. Il est aimable envers ses hôtes, généreux envers ceux qui le servent bien, et très discret sur ses propres affaires. Il ne dit pas ce qu'il veut. Il demande simplement, et attend de voir qui sera assez habile pour le faire.]=],
		},
		{
			title = "Importance",
			text = [=[La Ligue de Jorach est le plus ancien ennemi du {link:syndicate}Syndicat{/link} en {link:alterac-mountains}Alterac{/link}. Ses agents ne cherchent pas à tuer les membres du Syndicat un à un, car ils sont trop nombreux. Ils volent leurs emblèmes, et les déshonorés sont ensuite punis par les leurs. C'est une guerre plus discrète que celle que mène {link:southshore}Southshore{/link}, et peut-être plus efficace.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il règne sur le {link:ravenholdt-manor}Manoir de Ravenholdt{/link} et sur les voleurs qui s'y forment.
• Il mène contre le {link:syndicate}Syndicat{/link} une longue guerre de vol et de peur.
• Il fait appel à des voleurs de confiance pour récupérer ce qui lui est cher, et il les récompense richement.]=],
		},
		{
			title = "Non consigné",
			text = [=[Peu de choses sont écrites sur la vie de Jorach avant la Ligue, ni sur la façon dont sa maison en vint à tenir ces collines. Cette entrée ne rapporte que ce que ses actes révèlent.]=],
		},
	},
	chapters = {
		{
			title = "Une simple requête",
			hint = "Répondez à la convocation du seigneur de Ravenholdt.",
			text = [=[La convocation arriva en secret, et Jorach accueillit son invité chaleureusement. Il avait perdu une petite chose : un sac bleu. Les voleurs qui l'avaient pris étaient déjà morts. Ils n'avaient pas réussi à l'ouvrir et l'avaient vendu aux {link:timbermaw-furbolgs}Grumegueules{/link} d'{link:azshara}Azshara{/link}, qui le prirent pour une relique sacrée. Jorach voulait le récupérer, par la subtilité si possible.]=],
		},
		{
			title = "La clé d'azur",
			hint = "Rapportez la clé du sac perdu.",
			text = [=[Le sac était scellé par un enchantement, et sa clé se trouvait auprès d'un drake vert dans le temple englouti du {link:swamp-of-sorrows}Marais des Chagrins{/link}. Quand la clé lui fut rendue, Jorach ouvrit le sac. Une lumière dorée se répandit sur lui, et ses yeux s'écarquillèrent. Ce qu'il vit à l'intérieur, il ne le dit pas.]=],
		},
	},
	mentions = {
		{
			text = [=[Le manoir de {link:ravenholdt-manor}Ravenholdt{/link}, l'invitation envoyée en son nom]=],
		},
		{ text = "Emblèmes du {link:syndicate}Syndicat{/link}" },
		{ text = "Une simple requête" },
		{ text = "Sac d'azur scellé" },
		{ text = "La clé d'azur" },
	},
	bonds = {
		{ id = "fahrad", name = "Fahrad", note = "son grand maître voleur" },
		{ id = "lord-aliden-perenolde", name = "Lord Aliden Perenolde", note = "le seigneur de ses ennemis" },
	},
})

Translate("frFR", "fahrad", {
	title = "Fahrad",
	subtitle = "Grand maître voleur",
	found = "Manoir de Ravenholdt",
	hint = [=[Cherchez le maître voleur qui rédige les invitations pour Ravenholdt.]=],
	allegiance = "Ligue des assassins · Ravenholdt",
	sections = {
		{
			title = "Résumé",
			text = [=[Fahrad est le grand maître voleur de {link:ravenholdt-manor}Ravenholdt{/link}. C'est lui qui observe les jeunes voleurs du monde et décide lesquels valent la peine d'être formés. Ses lettres les trouvent où qu'ils soient, scellées de la marque du manoir. Ceux qui viennent doivent d'abord survivre à une épreuve de ruse sur la route. Fahrad accueille les survivants d'un éclat de rire.]=],
		},
		{
			title = "Importance",
			text = [=[Fahrad est la porte de la Ligue des assassins. Nul n'y entre sans passer entre ses mains.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il invite à {link:ravenholdt-manor}Ravenholdt{/link} les voleurs prometteurs et les met à l'épreuve en chemin.
• Il achète les coffrets que ses voleurs ouvrent sur le terrain.]=],
		},
	},
	mentions = {
		{ text = "Le manoir de {link:ravenholdt-manor}Ravenholdt{/link}" },
		{ text = "On a besoin de coffrets" },
	},
	bonds = {
		{ id = "lord-jorach-ravenholdt", name = "Lord Jorach Ravenholdt", note = "son maître" },
	},
})

Translate("frFR", "aiden-perenolde", {
	title = "Aiden Perenolde",
	subtitle = "Le roi traître d'Alterac",
	hint = [=[Découvrez l'histoire du roi qui vendit ses montagnes à la Horde.]=],
	allegiance = "Royaume d'Alterac",
	aliases = { "roi Perenolde", "lord Aiden Perenolde" },
	sections = {
		{
			title = "Résumé",
			text = [=[Aiden Perenolde fut le dernier roi d'{link:alterac-mountains}Alterac{/link}. C'était un homme cultivé, à la voix douce, qui possédait une belle épée et ne s'en servit jamais. Ses rivaux de l'{link:alliance}Alliance{/link} le tenaient pour un lâche. Il se tenait pour le seul roi assez sage pour voir que la {link:horde}Horde{/link} ne pouvait être vaincue. Durant la {link:second-war}Deuxième Guerre{/link}, il trahit l'Alliance pour sauver son propre royaume, et ce faisant il le perdit.]=],
		},
		{
			title = "Importance",
			text = [=[La traîtrise de Perenolde est la raison pour laquelle {link:alterac-mountains}Alterac{/link} gît en ruine. Ses héritiers rêvent encore de la couronne qu'il a perdue, et le {link:syndicate}Syndicat{/link} qu'ils dirigent est son amer héritage.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il ne rejoignit l'{link:alliance}Alliance de Lordaeron{/link} qu'à contrecœur, et en douta dès le début.
• Il barricada les cols de ses montagnes, puis conclut un pacte secret avec {link:orgrim-doomhammer}Orgrim Doomhammer{/link} et les ouvrit.
• Il assassina le messager qui apportait l'appel aux troupes de {link:anduin-lothar}Lothar{/link}, et cacha le corps dans son château.
• Il fut déposé par le {link:terenas-menethil}roi Terenas{/link} et confiné dans son palais de la capitale en ruine.]=],
		},
		{
			title = "Non consigné",
			text = [=[Nulle chronique ne rapporte quand ni comment mourut Aiden Perenolde. On dit que sa raison le quitta durant sa captivité. Sa famille fut placée sous surveillance, et son fils aîné, {link:lord-aliden-perenolde}Aliden{/link}, tenta en vain de laver leur nom.]=],
		},
	},
	chapters = {
		{
			title = "Les cols ouverts",
			hint = "Découvrez pourquoi la Horde traversa Alterac si vite.",
			text = [=[Quand la {link:horde}Horde{/link} arriva dans les montagnes, Perenolde envoya un oiseau à son chef de guerre et le rencontra de nuit. Il trouva l'{link:orcs}orc{/link} cultivé et honorable. Ils conclurent un traité : la Horde passerait sans encombre, et {link:alterac-mountains}Alterac{/link} serait épargnée. Perenolde déplaça ses soldats vers le nord et laissa vides les cols du sud. Une traversée qui aurait dû prendre des mois prit deux jours. Ce n'est que lorsque {link:thoras-trollbane}Thoras Trollbane{/link} de {link:stromgarde-keep}Stromgarde{/link} entra en Alterac et retourna contre Perenolde son propre général que les cols furent de nouveau fermés.]=],
		},
		{
			title = "Le bijou perdu",
			hint = "Récupérez le diadème de la maison royale d'Alterac.",
			text = [=[Quand {link:alterac-mountains}Alterac{/link} tomba, le diadème des Perenolde fut perdu. Des joailliers nains l'avaient façonné, et ses émeraudes étaient les plus belles qu'ils possédaient. Des collectionneurs de {link:stormwind-city}Stormwind{/link} le convoitent encore. Il reparut enfin entre les mains d'un {link:ogres}ogre{/link}-mage qui cherche des trésors dans les ruines de la cité même où le roi le portait jadis.]=],
		},
	},
	mentions = {
		{ text = "Le diadème des Perenolde" },
		{ text = "Morts nobles, contre les nobles de sa cour déchue" },
	},
	bonds = {
		{ id = "lord-aliden-perenolde", name = "Lord Aliden Perenolde", note = "son fils aîné" },
		{ id = "orgrim-doomhammer", name = "Orgrim Doomhammer", note = "son allié secret" },
		{ id = "terenas-menethil", name = "Terenas Menethil", note = "le roi qui le déposa" },
		{ id = "grel-borg-the-miser", name = "Grel'borg l'Avare", note = "détient le diadème de sa famille" },
	},
})

Translate("frFR", "lord-aliden-perenolde", {
	title = "Lord Aliden Perenolde",
	subtitle = "Seigneur du Syndicat",
	found = "Le Clos de Dandred, au bord du Lac Lordamere",
	hint = [=[Cherchez le seigneur du Syndicat dans son manoir au bord du lac.]=],
	allegiance = "Syndicat · Maison Perenolde",
	aliases = { "Aliden Perenolde", "Aliden" },
	sections = {
		{
			title = "Résumé",
			text = [=[Lord Aliden Perenolde est le fils aîné du roi traître d'{link:alterac-mountains}Alterac{/link} et le chef du {link:syndicate}Syndicat{/link}. Il se proclame seigneur des montagnes que son père a perdues. Depuis son manoir du {link:dandred-s-fold}Clos de Dandred{/link}, il dirige voleurs, assassins et nobles déchus à travers Alterac et {link:hillsbrad-foothills}Hillsbrad{/link}. Il ne cache pas ses ambitions. Il entend reprendre ces terres, et réduire en esclavage les orcs qui se dressent contre lui.]=],
		},
		{
			title = "Importance",
			text = [=[Aliden est l'héritier de la honte d'{link:alterac-mountains}Alterac{/link}. Il tenta jadis de racheter le nom de sa maison. Il est désormais devenu ce que ses ennemis ont toujours dit qu'il était.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il dirige le {link:syndicate}Syndicat{/link} depuis le {link:dandred-s-fold}Clos de Dandred{/link}, {link:argus-wake}l'Argus Wake{/link} à ses côtés.
• Il retient comme esclaves des captifs de la {link:horde}Horde{/link} dans les camps d'{link:alterac-mountains}Alterac{/link}.
• Il garde une jeune femme nommée {link:elysa}Elysa{/link} comme maîtresse, et lui donna un pendentif pris à {link:durnholde-keep}Durnholde{/link}.]=],
		},
	},
	chapters = {
		{
			title = "L'héritage de Blackmoore",
			hint = [=[Libérez l'orc captif du Syndicat et écoutez ce qu'il a appris.]=],
			text = [=[Aliden vint voir en personne son prisonnier {link:gol-dir}Gol'dir{/link}. Il se vanta devant l'{link:orcs}orc{/link} de ses projets : les orcs qui le défiaient seraient réduits en esclavage, comme l'avaient jadis voulu son père et son ancien mentor, {link:aedelas-blackmoore}Aedelas Blackmoore{/link}. À ses côtés se tenait {link:elysa}Elysa{/link}. À son cou pendait un pendentif que Gol'dir reconnut aussitôt, car c'était celui que son chef de guerre l'avait envoyé chercher.]=],
		},
		{
			title = "Le cadeau de Taretha",
			hint = "Portez la réponse des orcs au manoir du bord du lac.",
			text = [=[Les orcs de {link:tarren-mill}Moulin-de-Tarren{/link} répondirent à ses vantardises par l'acier. Ils vinrent au {link:dandred-s-fold}Clos de Dandred{/link} et tuèrent le seigneur du {link:syndicate}Syndicat{/link} dans sa propre maison. {link:elysa}Elysa{/link} implora qu'on l'épargne et rendit aussitôt le pendentif. Elle ne voulait garder aucun souvenir de lui, dit-elle.]=],
		},
	},
	mentions = {
		{ text = "L'héritage de {link:aedelas-blackmoore}Blackmoore{/link}" },
		{ text = "Lord Aliden Perenolde" },
		{ text = "Le cadeau de {link:taretha-foxton}Taretha{/link}" },
	},
	bonds = {
		{ id = "aiden-perenolde", name = "Aiden Perenolde", note = "son père" },
		{ id = "elysa", name = "Elysa", note = "sa maîtresse" },
		{ id = "nagaz", name = "Nagaz", note = "l'émissaire à ses côtés" },
		{ id = "aedelas-blackmoore", name = "Aedelas Blackmoore", note = "son mentor" },
		{ id = "gol-dir", name = "Gol'dir", note = "son prisonnier" },
		{ id = "lord-jorach-ravenholdt", name = "Lord Jorach Ravenholdt", note = "son ennemi" },
	},
})

