			text = [=[Belamoore détient ce que les {link:forsaken}Réprouvés{/link} désirent le plus en {link:alterac-mountains}Alterac{/link}. Par elle, la querelle entre le {link:kirin-tor}Kirin Tor{/link} et {link:undercity}Undercity{/link} est devenue une affaire de sang.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle retient les voleurs réprouvés dans le camp.
• Elle étudie les quatre artefacts de sanguinite qu'ils portaient.]=],
		},
	},
	mentions = {
		{ text = "Évasion à l'envers" },
	},
	bonds = {
