	},
})

Translate("frFR", "kegan-darkmar", {
	title = "Kegan Darkmar",
	subtitle = "Déserteur d'Undercity",
	found = "Camp d'internement de Lordamere",
	hint = [=[Trouvez le déserteur réprouvé retenu dans le camp près de Dalaran.]=],
	allegiance = "Aucune (déserteur réprouvé)",
	aliases = { "Kegan" },
	sections = {
		{
			title = "Résumé",
			text = [=[Kegan Darkmar est l'un des quatre {link:forsaken}Réprouvés{/link} qui ont tourné le dos à {link:undercity}Undercity{/link}. Ils forcèrent une chambre forte sécurisée de {link:sylvanas-windrunner}la Dame noire{/link}, volèrent quatre artefacts dont ses apothicaires avaient besoin, et s'enfuirent à {link:dalaran}Dalaran{/link}. Les sorciers ne les accueillirent pas. Ils mirent les quatre en quarantaine au {link:lordamere-internment-camp}Camp d'internement de Lordamere{/link}. Kegan et ses camarades Ricter, Alina et Dermot y attendent désormais, entre les magi qui les retiennent et les Réprouvés qui les traquent.]=],
		},
		{
			title = "Importance",
			text = [=[La fuite de Kegan montre que tous les {link:forsaken}Réprouvés{/link} ne se contentent pas de servir {link:sylvanas-windrunner}la Dame noire{/link}.]=],
		},
		{
			title = "Non consigné",
			text = [=[Nulle chronique ne rapporte pourquoi les quatre s'enfuirent, ni ce qu'ils espéraient trouver à {link:dalaran}Dalaran{/link}.]=],
		},
