	mentions = {
		{ text = "Évasion à l'envers" },
	},
	bonds = {
		{ id = "warden-belamoore", name = "Gardienne Belamoore", note = "sa geôlière" },
		{ id = "magus-wordeen-voidglare", name = "Magus Wordeen Voidglare", note = "le traque" },
	},
})

Translate("frFR", "prospector-stonehewer", {
