Translate("frFR", "vanndar-stormpike", {
	title = "Vanndar Stormpike",
	subtitle = "Général de la Garde Stormpike",
	found = "Dun Baldar, au nord de la vallée d'Alterac",
	hint = [=[Cherchez le général nain dans sa forteresse, à l'extrémité nord de la vallée d'Alterac.]=],
	allegiance = "Garde Stormpike · Royaume d'Ironforge",
	aliases = { "Vanndar" },
	sections = {
		{
			title = "Résumé",
			text = [=[Vanndar Stormpike est le général de la {link:stormpike-guard}Garde Stormpike{/link}, l'expédition naine entrée dans la vallée d'{link:alterac-mountains}Alterac{/link}. Depuis sa forteresse de Dun Baldar, au nord de la vallée, il commande des nains et leurs alliés de toutes les races de l'{link:alliance}Alliance{/link}. C'est un seigneur des montagnes aux mots rares et au dessein arrêté. La vallée, promet-il, sera à eux.]=],
		},
		{
			title = "Importance",
			text = [=[Vanndar est la lance d'{link:kingdom-of-ironforge}Ironforge{/link} dans le nord. Son expédition vint, dit-on, creuser pour trouver du minerai et des reliques du passé. Son roi lui a confié une tâche plus rude : prendre les vallées d'{link:alterac-mountains}Alterac{/link} et les tenir pour {link:ironforge}Ironforge{/link}. Cette tâche l'a mis en guerre contre le {link:frostwolf-clan}clan Frostwolf{/link}, dont la vallée est le foyer depuis que les Frostwolf y furent exilés.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il dirige la {link:stormpike-guard}Garde Stormpike{/link} depuis Dun Baldar.
• Il fait la guerre au {link:frostwolf-clan}clan Frostwolf{/link} et aux trolls Winterax de la vallée.
• Il accueille les soldats que l'{link:alliance}Alliance{/link} envoie dans la vallée.]=],
		},
		{
			title = "Non consigné",
			text = [=[Peu de choses sont écrites sur Vanndar avant l'expédition, ni sur sa parenté avec d'autres nains qui portent le nom de {link:stormpike-guard}Stormpike{/link}.]=],
		},
	},
	chapters = {
		{
			title = "L'impératif souverain",
			hint = "Répondez à l'appel d'Ironforge vers les vallées d'Alterac.",
			text = [=[L'appel fut lancé au nom du roi {link:magni-bronzebeard}Magni Bronzebeard{/link}. Les {link:stormpike-guard}Stormpike{/link} combattaient des trolls d'un côté et des orcs de l'autre, et ils avaient besoin de soldats. La conquête de ces terres, déclarèrent les nains, était le droit et le devoir d'{link:ironforge}Ironforge{/link}. On dit aux nouvelles recrues de trouver le lieutenant Haggerdin à l'extérieur de la vallée et de commencer leur service parmi les Stormpike.]=],
		},
		{
			title = "La bataille pour Alterac",
			hint = "Dressez-vous contre le général de Dun Baldar.",
			text = [=[Les {link:frostwolf-clan}Frostwolf{/link} voient les choses autrement. Pour eux, les {link:stormpike-guard}Stormpike{/link} sont des envahisseurs. Leurs guerriers entendent se frayer un chemin vers le nord à travers la vallée jusqu'à Dun Baldar et abattre le général dans sa propre forteresse.]=],
		},
	},
	mentions = {
		{ text = "L'impératif souverain" },
		{ text = "La bataille pour {link:alterac-mountains}Alterac{/link}" },
		{ text = "Terrain d'épreuve" },
	},
	bonds = {
		{ id = "drek-thar", name = "Drek'Thar", note = "son ennemi" },
		{ id = "magni-bronzebeard", name = "Magni Bronzebeard", note = "son roi" },
		{ id = "prospector-stonehewer", name = "Prospectrice Stonehewer", note = "cherche des reliques pour l'expédition" },
	},
})

Translate("frFR", "drek-thar", {
	title = "Drek'Thar",
	subtitle = "Ancien chaman du clan Frostwolf",
	found = "Donjon Frostwolf, au sud de la vallée d'Alterac",
	hint = [=[Cherchez le vieux chaman qui règne depuis le Donjon Frostwolf, à l'extrémité sud de la vallée d'Alterac.]=],
	allegiance = "Clan Frostwolf · Horde",
	aliases = { "Drek'thar" },
	sections = {
		{
			title = "Résumé",
			text = [=[Drek'Thar est l'ancien chaman du {link:frostwolf-clan}clan Frostwolf{/link} et le général de ses guerriers dans la vallée d'{link:alterac-mountains}Alterac{/link}. Il est aveugle, et il est vieux. Il était chaman des Frostwolf sur Draenor, et il suivit son peuple en exil dans ces montagnes. Il y a longtemps, il prit sous sa protection un jeune {link:orcs}orc{/link} nommé {link:thrall}Thrall{/link} et lui apprit à parler aux esprits. Il mène désormais les Frostwolf depuis leur donjon au sud de la vallée.]=],
		},
		{
			title = "Importance",
			text = [=[Drek'Thar est le maître du chef de guerre. Par lui, les anciennes voies du chaman revinrent aux orcs, et par {link:thrall}Thrall{/link} elles revinrent à toute la {link:horde}Horde{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il maintint les {link:frostwolf-clan}Frostwolf{/link} en vie durant leur exil en {link:alterac-mountains}Alterac{/link}.
• Il enseigna à {link:thrall}Thrall{/link} la voie du chaman et lui révéla qui étaient ses parents.
• Il dirige la défense de la vallée d'Alterac contre la {link:stormpike-guard}Garde Stormpike{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Le fils de Durotan",
			hint = "Découvrez comment le chef de guerre vint aux Frostwolf.",
			text = [=[Quand un jeune {link:orcs}orc{/link} élevé par des humains arriva au camp des {link:frostwolf-clan}Frostwolf{/link}, il portait une couverture déchirée datant de sa petite enfance. Drek'Thar en reconnut les motifs. L'étranger était le fils de Durotan, le chef qui avait mené le clan en exil et qui avait été assassiné avec sa compagne. Le vieux chaman éprouva la fierté et l'humilité du jeune orc, puis lui enseigna les voies des esprits.]=],
		},
		{
			title = "Pour la défense des Frostwolf",
			hint = "Tenez-vous aux côtés des Frostwolf dans leur vallée.",
			text = [=[Aujourd'hui, des nains sont entrés dans la vallée qui abrita les {link:frostwolf-clan}Frostwolf{/link} durant leurs années les plus sombres. Le clan cher au chef de guerre est attaqué, et l'appel a retenti à travers toute la {link:horde}Horde{/link}. Les guerriers sont envoyés au nord de {link:tarren-mill}Moulin-de-Tarren{/link} auprès du maître de guerre Laggrond, qui les met à l'épreuve à l'entrée de la vallée avant qu'ils ne combattent.]=],
		},
	},
	mentions = {
		{ text = "Pour la défense des {link:frostwolf-clan}Frostwolf{/link}" },
		{ text = "La bataille d'{link:alterac-mountains}Alterac{/link}" },
		{ text = "Terrain d'épreuve" },
	},
	bonds = {
		{ id = "thrall", name = "Thrall", note = "son élève et chef de guerre" },
		{ id = "vanndar-stormpike", name = "Vanndar Stormpike", note = "son ennemi" },
		{ id = "voggah-deathgrip", name = "Voggah Deathgrip", note = "envoie des guerriers à son aide" },
	},
})

Translate("frFR", "crushridge-ogres", {
	title = "Ogres Cassecrête",
	aliases = { "Cassecrête", "ogre Cassecrête", "clan Cassecrête" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Cassecrête sont une bande guerrière d'{link:ogres}ogres{/link} qui a fait siennes les ruines de l'ancienne capitale d'{link:alterac-mountains}Alterac{/link}. Brutes, cogneurs, bellicistes, hommes de main et mages emplissent les rues où chevauchaient jadis les rois d'Alterac. Ils ont creusé un grand tertre dans les collines voisines et un second plus loin dans les montagnes, et leurs patrouilles gardent le carrefour qui mène vers {link:tarren-mill}Moulin-de-Tarren{/link}.]=],
		},
		{
			title = "La Couronne de volonté",
			text = [=[Les Cassecrête ne vinrent pas en {link:alterac-mountains}Alterac{/link} de leur plein gré. Leur seigneur de guerre {link:mug-thol}Mug'thol{/link} était lié au service de {link:sylvanas-windrunner}Sylvanas Windrunner{/link}, et elle envoya sa bande dans les montagnes récupérer une relique appelée la Couronne de volonté. Mug'thol trouva la couronne et la posa sur sa tête. Elle le libéra de l'emprise de la Dame noire, et ses ogres le suivirent dans les ruines en maîtres d'eux-mêmes. Trois lieutenants, Targ, Muckrake et Glommus, se tiennent à ses côtés, et l'{link:ogres}ogre{/link}-mage {link:grel-borg-the-miser}Grel'borg{/link} fouille la cité en quête de trésors.]=],
		},
		{
			title = "Des ennemis de tous côtés",
			text = [=[Les {link:forsaken}Réprouvés{/link} de {link:tarren-mill}Moulin-de-Tarren{/link} veulent la couronne, et avec elle les têtes de {link:mug-thol}Mug'thol{/link} et de ses lieutenants. Les soldats de {link:southshore}Southshore{/link} craignent que les ogres ne descendent dans les contreforts, et leur maréchal paie une prime pour chaque {link:ogres}ogre{/link} tué. Les ogres ont aussi combattu le {link:syndicate}Syndicat{/link} pour les ruines du royaume que tous deux revendiquent.]=],
		},
	},
})

Translate("frFR", "argus-wake", {
	title = "Argus Wake",
	aliases = { "l'Argus Wake" },
	sections = {
		{
			title = "Résumé",
			text = [=[L'Argus Wake est un ordre secret qui s'est fait l'allié du {link:syndicate}Syndicat{/link} en {link:alterac-mountains}Alterac{/link}. Ses mages de l'ombre attendent dans les {link:the-uplands}Hauteurs{/link}, et son hiérophante, l'{link:orcs}orc{/link} {link:nagaz}Nagaz{/link}, se tient aux côtés de lord {link:lord-aliden-perenolde}Aliden Perenolde{/link}. Les nobles d'Alterac croient avoir trouvé de puissants amis. Ils se trompent.]=],
		},
		{
			title = "La lettre",
			text = [=[La vérité éclata grâce à une lettre trouvée dans un camp du {link:syndicate}Syndicat{/link}. Elle était écrite en un chiffre si rare que même le maître des traditions de {link:southshore}Southshore{/link} ne put la lire, et il fallut la porter à un prospecteur d'{link:ironforge}Ironforge{/link}. {link:nagaz}Nagaz{/link} l'avait écrite au chef de l'Argus Wake, qu'il appelait son maître, nommé par un conseil. Le Syndicat, écrivait-il, reprendrait {link:alterac-mountains}Alterac{/link} sous la conduite de l'Argus Wake, puis prendrait {link:stromgarde-keep}Stromgarde{/link}. Avec une nation et une base de pouvoir bien à elle, l'Argus Wake préparerait alors la venue de ce qu'il appelait la Troisième Armée. Il signa au nom de {link:sargeras}Sargeras{/link}.]=],
		},
		{
			title = "Ce qui demeure inconnu",
			text = [=[Le {link:magistrate-henry-maleb}magistrat Maleb{/link} de {link:southshore}Southshore{/link} envoya des chasseurs aux trousses de {link:nagaz}Nagaz{/link} et de ses mages. Malgré tout, le magistrat sait que Nagaz n'était qu'un serviteur. Qui dirige l'Argus Wake, et jusqu'où s'étendent ses racines, nul à Southshore ne saurait le dire.]=],
		},
	},
})

Translate("frFR", "stormpike-guard", {
	title = "Garde Stormpike",
	aliases = { "expédition Stormpike", "Stormpike" },
	sections = {
		{
			title = "Résumé",
			text = [=[La Garde Stormpike est une expédition de {link:dwarves}nains{/link} du clan Stormpike dans la vallée d'{link:alterac-mountains}Alterac{/link}, sous le commandement du général {link:vanndar-stormpike}Vanndar Stormpike{/link}. Depuis leur forteresse de Dun Baldar, au nord de la vallée, ils fouillent la terre à la recherche de minerai et de reliques de leur passé. Des humains, des gnomes et des elfes de la nuit de l'{link:alliance}Alliance{/link} combattent dans leurs rangs.]=],
		},
		{
			title = "L'impératif",
			text = [=[L'expédition est devenue une guerre. Le roi {link:magni-bronzebeard}Magni Bronzebeard{/link} a déclaré que la conquête des vallées d'{link:alterac-mountains}Alterac{/link} était un devoir du {link:kingdom-of-ironforge}royaume d'Ironforge{/link}, et les Stormpike se battent pour les revendiquer contre les trolls Winterax et les orcs du {link:frostwolf-clan}clan Frostwolf{/link}. Les érudits de la {link:explorers-league}Ligue des explorateurs{/link} marchent avec eux, certains que la vallée recèle des artefacts qui valent ce combat. Les orcs les appellent des envahisseurs. Les nains disent que la vallée leur revient de droit.]=],
		},
		{
			title = "Le temps présent",
			text = [=[À l'extérieur du tunnel qui mène à la vallée, des officiers Stormpike accueillent les soldats de l'{link:alliance}Alliance{/link}, les mettent à l'épreuve dans les cavernes de la vallée et leur remettent l'insigne de la Garde. Les béliers des nains, élevés à la {link:amberstill-ranch}Ferme des Amberstill{/link}, en {link:dun-morogh}Dun Morogh{/link}, partent vers le nord renforcer l'expédition.]=],
		},
	},
})

Translate("frFR", "frostwolf-clan", {
	title = "Clan Frostwolf",
	aliases = { "Frostwolf", "clan Frostwolf", "orcs Frostwolf" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le clan Frostwolf est un clan {link:orcs}orc{/link} qui a fait son foyer de la vallée d'{link:alterac-mountains}Alterac{/link}. C'est le clan du père de {link:thrall}Thrall{/link}, et le chef de guerre lui est très attaché. Ses guerriers chevauchent les grands loups blancs des montagnes, et son ancien chaman, {link:drek-thar}Drek'Thar{/link}, le dirige depuis le Donjon Frostwolf, au sud de la vallée.]=],
		},
		{
			title = "L'exil",
			text = [=[Sur Draenor, les Frostwolf étaient un clan fier, sous la conduite de leur chef, Durotan. Quand les orcs vinrent en {link:azeroth}Azeroth{/link}, Durotan s'éleva contre {link:gul-dan}Gul'dan{/link} et la voie sombre que la {link:horde}Horde{/link} avait prise. Pour cela, son clan fut banni dans les montagnes d'{link:alterac-mountains}Alterac{/link}. Durotan et sa compagne quittèrent plus tard la vallée, et tous deux furent assassinés par des agents de Gul'dan. Leur fils encore nourrisson fut trouvé par un officier humain, qui l'éleva comme esclave à {link:durnholde-keep}Durnholde{/link}. Les Frostwolf endurèrent seuls le froid et les longues années, et loin de la gangrène de la Horde, leurs chamans réapprirent les voies des esprits.]=],
		},
		{
			title = "Le retour du fils",
			text = [=[Des années plus tard, un jeune {link:orcs}orc{/link} arriva à leur camp, un fugitif de {link:durnholde-keep}Durnholde{/link}. C'était le fils de Durotan. {link:drek-thar}Drek'Thar{/link} lui enseigna les voies du chaman, et c'est de la vallée que {link:thrall}Thrall{/link} partit libérer les orcs des camps et bâtir une nouvelle {link:horde}Horde{/link}.]=],
		},
		{
			title = "Le temps présent",
			text = [=[Aujourd'hui, les nains de la {link:stormpike-guard}Garde Stormpike{/link} sont entrés dans la vallée. Les Frostwolf ne livreront pas leur foyer, et la {link:horde}Horde{/link} a répondu à leur appel.]=],
		},
	},
})
